---@class AlwaysFail
local AlwaysFail = Class("AlwaysFail", Decorator)

function AlwaysFail:Update(context)
    assert(self._child ~= nil, "child 不能为空")
    
    local status = self._child:Update(context)
    if status == Decorator.TaskStatus.Running then
        return status
    end
    
    return Decorator.TaskStatus.Failure
end


return AlwaysFail
 